@page "/apply"
@rendermode InteractiveServer
@using sv_2a0d4712205f45aeb8fb30347417e5e3.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @* ───── Step Indicator Bar ───── *@
    <nav class="mb-4">
        <div class="d-flex justify-content-between position-relative">
            @for (int i = 0; i < _stepLabels.Length; i++)
            {
                var step = i + 1;
                var isCompleted = step < _currentStep;
                var isCurrent = step == _currentStep;
                var isFuture = step > _currentStep;

                <button type="button"
                        class="btn btn-link text-decoration-none p-0 d-flex flex-column align-items-center flex-fill @(isFuture && !_submitted ? "text-muted" : "")"
                        disabled="@(isFuture || _submitted)"
                        @onclick="() => GoToStep(step)"
                        style="border: none; background: none;">
                    <span class="rounded-circle d-flex align-items-center justify-content-center mb-1"
                          style="width: 36px; height: 36px;
                                 @(isCurrent ? "background-color: #0d6efd; color: white;" :
                                   isCompleted ? "background-color: #198754; color: white;" :
                                   "background-color: #dee2e6; color: #6c757d;")">
                        @if (isCompleted)
                        {
                            <span>✓</span>
                        }
                        else
                        {
                            <span>@step</span>
                        }
                    </span>
                    <small class="@(isCurrent ? "fw-bold text-primary" : isCompleted ? "text-success" : "")">
                        @_stepLabels[i]
                    </small>
                </button>
            }
        </div>
    </nav>

    @if (!_submitted)
    {
        @* ───── Validation Errors ───── *@
        @if (_errors.Count > 0)
        {
            <div class="alert alert-danger py-2">
                <ul class="mb-0 ps-3">
                    @foreach (var error in _errors)
                    {
                        <li>@error</li>
                    }
                </ul>
            </div>
        }

        @* ───── Step 1: Personal Info ───── *@
        @if (_currentStep == 1)
        {
            <h4>Personal Information</h4>
            <div class="mb-3">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_fullName" placeholder="John Doe" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="_email" placeholder="john@example.com" />
            </div>
            <div class="mb-3">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="_phone" placeholder="(555) 123-4567" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_address" placeholder="123 Main St, City, State" />
            </div>
            <div class="d-flex justify-content-end">
                <button class="btn btn-primary" @onclick="NextStep" disabled="@_isValidating">
                    @if (_isValidating)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                        <span>Validating…</span>
                    }
                    else
                    {
                        <span>Next →</span>
                    }
                </button>
            </div>
        }

        @* ───── Step 2: Work History ───── *@
        else if (_currentStep == 2)
        {
            <h4>Work History</h4>
            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var index = i;
                var entry = _workEntries[index];
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h6 class="mb-0">Position @(index + 1)</h6>
