@page "/apply"
@rendermode InteractiveServer
@using sv_2a0d4712205f45aeb8fb30347417e5e3.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @* ───── Step Indicator Bar ───── *@
    <nav class="mb-4">
        <div class="d-flex justify-content-between position-relative">
            @for (int i = 0; i < _stepLabels.Length; i++)
            {
                var step = i + 1;
                var isCompleted = step < _currentStep;
                var isCurrent = step == _currentStep;
                var isFuture = step > _currentStep;

                <button type="button"
                        class="btn btn-link text-decoration-none p-0 d-flex flex-column align-items-center flex-fill @(isFuture && !_submitted ? "text-muted" : "")"
                        disabled="@(isFuture || _submitted)"
                        @onclick="() => GoToStep(step)"
                        style="border: none; background: none;">
                    <span class="rounded-circle d-flex align-items-center justify-content-center mb-1"
                          style="width: 36px; height: 36px;
                                 @(isCurrent ? "background-color: #0d6efd; color: white;" :
                                   isCompleted ? "background-color: #198754; color: white;" :
                                   "background-color: #dee2e6; color: #6c757d;")">
                        @if (isCompleted)
                        {
                            <span>✓</span>
                        }
                        else
                        {
                            <span>@step</span>
                        }
                    </span>
                    <small class="@(isCurrent ? "fw-bold text-primary" : isCompleted ? "text-success" : "")">
                        @_stepLabels[i]
                    </small>
                </button>
            }
        </div>
    </nav>

    @if (!_submitted)
    {
        @* ───── Validation Errors ───── *@
        @if (_errors.Count > 0)
        {
            <div class="alert alert-danger py-2">
                <ul class="mb-0 ps-3">
                    @foreach (var error in _errors)
                    {
                        <li>@error</li>
                    }
                </ul>
            </div>
        }

        @* ───── Step 1: Personal Info ───── *@
        @if (_currentStep == 1)
        {
            <h4>Personal Information</h4>
            <div class="mb-3">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_fullName" placeholder="John Doe" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="_email" placeholder="john@example.com" />
            </div>
            <div class="mb-3">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="_phone" placeholder="(555) 123-4567" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_address" placeholder="123 Main St, City, State" />
            </div>
            <div class="d-flex justify-content-end">
                <button class="btn btn-primary" @onclick="NextStep" disabled="@_isValidating">
                    @if (_isValidating)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                        <span>Validating…</span>
                    }
                    else
                    {
                        <span>Next →</span>
                    }
                </button>
            </div>
        }

        @* ───── Step 2: Work History ───── *@
        else if (_currentStep == 2)
        {
            <h4>Work History</h4>
            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var index = i;
                var entry = _workEntries[index];
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h6 class="mb-0">Position @(index + 1)</h6>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>
                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Company <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Company"
                                       @onchange="e => UpdateWork(index, entry with { Company = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Title"
                                       @onchange="e => UpdateWork(index, entry with { Title = (string?)e.Value ?? string.Empty })" />
                            </div>
                        </div>
                        <div class="row mb-2">
                            <div class="col-md-4">
                                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                <input type="date" class="form-control" value="@entry.StartDate?.ToString("yyyy-MM-dd")"
                                       @onchange="e => UpdateWork(index, entry with { StartDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null })" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control" value="@entry.EndDate?.ToString("yyyy-MM-dd")"
                                       disabled="@entry.IsCurrent"
                                       @onchange="e => UpdateWork(index, entry with { EndDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null })" />
                            </div>
                            <div class="col-md-4 d-flex align-items-end mb-1">
                                <div class="form-check">
                                    <input type="checkbox" class="form-check-input" id="current-@index" checked="@entry.IsCurrent"
                                           @onchange="e => UpdateWork(index, entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = (bool)(e.Value ?? false) ? null : entry.EndDate })" />
                                    <label class="form-check-label" for="current-@index">Currently working here</label>
                                </div>
                            </div>
                        </div>
                        <div class="mb-2">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" rows="2" value="@entry.Description"
                                      @onchange="e => UpdateWork(index, entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
                        </div>
                    </div>
                </div>
            }
            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PrevStep">← Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next →</button>
            </div>
        }

        @* ───── Step 3: References ───── *@
        else if (_currentStep == 3)
        {
            <h4>References</h4>
            @for (int i = 0; i < _references.Count; i++)
            {
                var index = i;
                var reference = _references[index];
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h6 class="mb-0">Reference @(index + 1)</h6>
                            @if (_references.Count > 2)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>
                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Name <span class="text-danger">*</span></label>
                                <input class="form-control" value="@reference.Name"
                                       @onchange="e => UpdateReference(index, reference with { Name = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                <input class="form-control" value="@reference.Relationship"
                                       @onchange="e => UpdateReference(index, reference with { Relationship = (string?)e.Value ?? string.Empty })" />
                            </div>
                        </div>
                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Email <span class="text-danger">*</span></label>
                                <input type="email" class="form-control" value="@reference.Email"
                                       @onchange="e => UpdateReference(index, reference with { Email = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Phone <span class="text-danger">*</span></label>
                                <input type="tel" class="form-control" value="@reference.Phone"
                                       @onchange="e => UpdateReference(index, reference with { Phone = (string?)e.Value ?? string.Empty })" />
                            </div>
                        </div>
                    </div>
                </div>
            }
            @if (_references.Count < 3)
            {
                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PrevStep">← Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next →</button>
            </div>
        }

        @* ───── Step 4: Cover Letter ───── *@
        else if (_currentStep == 4)
        {
            <h4>Cover Letter</h4>
            <div class="mb-3">
                <textarea class="form-control" rows="10" maxlength="2000"
                          @bind="_coverLetter" placeholder="Write your cover letter here…"></textarea>
                <div class="form-text text-end">@(_coverLetter?.Length ?? 0) / 2000 characters</div>
            </div>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PrevStep">← Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next →</button>
            </div>
        }

        @* ───── Step 5: Review & Submit ───── *@
        else if (_currentStep == 5)
        {
            <h4>Review Your Application</h4>

            @* Personal Info Summary *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Personal Information</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(1)">Edit</button>
                </div>
                <div class="card-body">
                    <p class="mb-1"><strong>Name:</strong> @_fullName</p>
                    <p class="mb-1"><strong>Email:</strong> @_email</p>
                    <p class="mb-1"><strong>Phone:</strong> @_phone</p>
                    <p class="mb-0"><strong>Address:</strong> @_address</p>
                </div>
            </div>

            @* Work History Summary *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Work History</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(2)">Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var entry in _workEntries)
                    {
                        <div class="mb-2 @(entry != _workEntries.Last() ? "border-bottom pb-2" : "")">
                            <p class="mb-1"><strong>@entry.Title</strong> at @entry.Company</p>
                            <p class="mb-1 text-muted small">
                                @entry.StartDate?.ToString("MMM yyyy") –
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                            </p>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mb-0 small">@entry.Description</p>
                            }
                        </div>
                    }
                </div>
            </div>

            @* References Summary *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>References</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(3)">Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var reference in _references)
                    {
                        <div class="mb-2 @(reference != _references.Last() ? "border-bottom pb-2" : "")">
                            <p class="mb-1"><strong>@reference.Name</strong> — @reference.Relationship</p>
                            <p class="mb-0 small">@reference.Email · @reference.Phone</p>
                        </div>
                    }
                </div>
            </div>

            @* Cover Letter Summary *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Cover Letter</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(4)">Edit</button>
                </div>
                <div class="card-body">
                    <p style="white-space: pre-wrap;" class="mb-0">@_coverLetter</p>
                </div>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PrevStep">← Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                    @if (_isSubmitting)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                        <span>Submitting…</span>
                    }
                    else
                    {
                        <span>Submit Application</span>
                    }
                </button>
            </div>
        }
    }
    else
    {
        @* ───── Confirmation ───── *@
        <div class="text-center py-5">
            <div class="mb-3" style="font-size: 3rem;">✅</div>
            <h3 class="text-success">Application Submitted!</h3>
            <p class="lead">Your application ID is <strong>#@_applicationId</strong></p>
            <p class="text-muted">Thank you for applying, @_fullName. We will review your application and get back to you.</p>
        </div>
    }
</div>

@code {
    private static readonly string[] _stepLabels = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep = 1;
    private bool _submitted;
    private bool _isValidating;
    private bool _isSubmitting;
    private int _applicationId;
    private List<string> _errors = new();

    // Step 1 state
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2 state
    private List<WorkEntryModel> _workEntries = new() { new() };

    // Step 3 state
    private List<ReferenceModel> _references = new() { new(), new() };

    // Step 4 state
    private string _coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        if (step < _currentStep && !_submitted)
        {
            _errors.Clear();
            _currentStep = step;
        }
    }

    private void PrevStep()
    {
        _errors.Clear();
        if (_currentStep > 1) _currentStep--;
    }

    private async Task NextStep()
    {
        _errors.Clear();

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 1)
        {
            _isValidating = true;
            StateHasChanged();
            var isValid = await ApplicationService.ValidateEmailAsync(_email);
            _isValidating = false;
            if (!isValid)
            {
                _errors.Add("Please enter a valid email address.");
                return;
            }
        }

        _currentStep++;
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 1:
                if (string.IsNullOrWhiteSpace(_fullName)) _errors.Add("Full name is required.");
                if (string.IsNullOrWhiteSpace(_email)) _errors.Add("Email is required.");
                if (string.IsNullOrWhiteSpace(_phone)) _errors.Add("Phone is required.");
                if (string.IsNullOrWhiteSpace(_address)) _errors.Add("Address is required.");
                break;
            case 2:
                for (int i = 0; i < _workEntries.Count; i++)
                {
                    var e = _workEntries[i];
                    if (string.IsNullOrWhiteSpace(e.Company)) _errors.Add($"Position {i + 1}: Company is required.");
                    if (string.IsNullOrWhiteSpace(e.Title)) _errors.Add($"Position {i + 1}: Job title is required.");
                    if (e.StartDate is null) _errors.Add($"Position {i + 1}: Start date is required.");
                }
                break;
            case 3:
                for (int i = 0; i < _references.Count; i++)
                {
                    var r = _references[i];
                    if (string.IsNullOrWhiteSpace(r.Name)) _errors.Add($"Reference {i + 1}: Name is required.");
                    if (string.IsNullOrWhiteSpace(r.Relationship)) _errors.Add($"Reference {i + 1}: Relationship is required.");
                    if (string.IsNullOrWhiteSpace(r.Email)) _errors.Add($"Reference {i + 1}: Email is required.");
                    if (string.IsNullOrWhiteSpace(r.Phone)) _errors.Add($"Reference {i + 1}: Phone is required.");
                }
                break;
            case 4:
                if (string.IsNullOrWhiteSpace(_coverLetter)) _errors.Add("Cover letter is required.");
                break;
        }
        return _errors.Count == 0;
    }

    // Work entry helpers
    private void AddWorkEntry() => _workEntries.Add(new());
    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);
    private void UpdateWork(int index, WorkEntryModel entry) => _workEntries[index] = entry;

    // Reference helpers
    private void AddReference() { if (_references.Count < 3) _references.Add(new()); }
    private void RemoveReference(int index) => _references.RemoveAt(index);
    private void UpdateReference(int index, ReferenceModel reference) => _references[index] = reference;

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        StateHasChanged();

        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
        var work = new WorkHistory(_workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
        var refs = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        var application = new JobApplication(personal, work, refs, _coverLetter);

        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
        _isSubmitting = false;
        _submitted = true;
    }

    // Mutable helper models for form binding
    private record WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private record ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}
